mapper.select:
select total.TOTLE_TRADE_ID totleTradeId, deal.TRADE_ID tradeId, total.PORTFOLIO_ID portfolioId, ptl1.PORTFOLIO_NAME portfolioName, dealAdd.PORTFOLIO_ID subPortfolioId, ptl2.PORTFOLIO_NAME subPortfolioName, dis.DIS_PERCENT*100 disPercent, ptl2.REMARK remark, DATE_FORMAT(total.SETTLE_DATE,'%Y-%m-%d') settleDate, deal.CCY ccy,
case when deal.PS='C4' then deal.TRADE_AMT*(-1) else deal.TRADE_AMT end tradeAmt, deal.REMARK deployrRemark , ptl1.PARENT_PORTFOLIO_ID parentPortfolioId from TRD_FIN_PRODUCT_DEAL_TOTAL total left join PA_TRD_FIN_PRODUCT_DEAL_TOTAL paTotal on total.TOTLE_TRADE_ID = paTotal.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL deal on deal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD dealAdd on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO_DIS dis on dis.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join PTL_PORTFOLIO ptl1 on ptl1.PORTFOLIO_ID = total.PORTFOLIO_ID left join PTL_PORTFOLIO ptl2 on ptl2.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID where total.FINPROD_TYPE2 = #{finprodType2} and paTotal.PA_BUSS_TYPE = #{paBussType} and total.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId})
and total.PORTFOLIO_ID in
#{item}
and total.SETTLE_DATE >= STR_TO_DATE(#{settleDateBegin},'%Y-%m-%d')
and total.SETTLE_DATE <= STR_TO_DATE(#{settleDateEnd},'%Y-%m-%d')
and IFNULL(total.IS_CANCEL,' ') <> #{isCancle}
and dealAdd.PORTFOLIO_ID in
#{item}
order by total.TRADE_DATE,total.PORTFOLIO_ID,total.TOTLE_TRADE_ID desc

select total.TOTLE_TRADE_ID totleTradeId, deal.TRADE_ID tradeId, total.PORTFOLIO_ID portfolioId, ptl1.PORTFOLIO_NAME portfolioName, dealAdd.PORTFOLIO_ID subPortfolioId, ptl2.PORTFOLIO_NAME subPortfolioName, dis.DIS_PERCENT*100 disPercent, ptl2.REMARK remark, DATE_FORMAT(total.SETTLE_DATE,'%Y-%m-%d') settleDate, deal.CCY ccy, case when deal.PS='C4' then deal.TRADE_AMT*(-1) else deal.TRADE_AMT end tradeAmt, deal.REMARK deployrRemark ,A.actualAmt from TRD_FIN_PRODUCT_DEAL_TOTAL total left join TRD_PRODUCT_DEAL deal on deal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD dealAdd on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO_DIS dis on dis.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join PTL_PORTFOLIO ptl1 on ptl1.PORTFOLIO_ID = total.PORTFOLIO_ID left join PTL_PORTFOLIO ptl2 on ptl2.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join ( select IFNULL(SUM(PF.AMOUNT),0) actualAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY WHERE 1=1 and PF.PORTFOLIO_ID IN (select T1.PORTFOLIO_ID from PTL_PORTFOLIO T1 where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{parentPortfolioId}
)
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY) A on dealAdd.PORTFOLIO_ID = A.subPortfolioId and deal.CCY = A.ccy
where 1=1
AND total.TOTLE_TRADE_ID = #{totleTradeId}
order by total.TRADE_DATE,total.PORTFOLIO_ID,total.TOTLE_TRADE_ID desc

select total.TOTLE_TRADE_ID totleTradeId, deal.TRADE_ID tradeId, total.PORTFOLIO_ID portfolioId, ptl1.PORTFOLIO_NAME portfolioName, dealAdd.PORTFOLIO_ID subPortfolioId, ptl2.PORTFOLIO_NAME subPortfolioName, dis.DIS_PERCENT*100 disPercent, ptl2.REMARK remark, DATE_FORMAT(total.SETTLE_DATE,'%Y-%m-%d') settleDate, deal.CCY ccy, case when deal.PS='C4' then deal.TRADE_AMT*(-1) else deal.TRADE_AMT end tradeAmt, deal.REMARK deployrRemark ,A.actualAmt from wfl_trd_fin_product_deal_total total left join wfl_trd_product_deal deal on deal.TOTLE_TRADE_ID = total.TOTLE_TRADE_ID left join wfl_trd_product_deal_add dealAdd on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO_DIS dis on dis.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID left join PTL_PORTFOLIO ptl1 on ptl1.PORTFOLIO_ID = total.PORTFOLIO_ID left join PTL_PORTFOLIO ptl2 on ptl2.PORTFOLIO_ID = dealAdd.PORTFOLIO_ID
left join ( select IFNULL(SUM(PF.AMOUNT),0) actualAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF
INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY
WHERE 1=1 and PF.PORTFOLIO_ID IN (select T1.PORTFOLIO_ID from PTL_PORTFOLIO T1 where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{portfolioId}
)
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY) A on total.PORTFOLIO_ID = A.subPortfolioId and deal.CCY = A.ccy
where 1=1
AND total.TOTLE_TRADE_ID = #{totleTradeId}
order by total.TRADE_DATE,total.PORTFOLIO_ID,total.TOTLE_TRADE_ID desc

select T1.PARENT_PORTFOLIO_ID parentPortfolioId, T1.PORTFOLIO_ID portfolioId, T1.PORTFOLIO_NAME portfolioName, T1.PORTFOLIO_ID subPortfolioId, T1.PORTFOLIO_NAME subPortfolioName, dis.DIS_PERCENT*100 disPercent, T1.REMARK remark, A.actualAmt,A.ccy from PTL_PORTFOLIO T1 left join PTL_PORTFOLIO_DIS dis on dis.PORTFOLIO_ID = T1.PORTFOLIO_ID left join ( select IFNULL(SUM(PF.AMOUNT),0) actualAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF
INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY
WHERE 1=1 and PF.PORTFOLIO_ID IN (select T1.PORTFOLIO_ID from PTL_PORTFOLIO T1 where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{portfolioId}
)
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY) A on T1.PORTFOLIO_ID = A.subPortfolioId where 1=1
AND T1.PARENT_PORTFOLIO_ID = #{portfolioId}

		select
		    IFNULL(SUM(AMOUNT),0) actualAmt,
		    PORTFOLIO_ID subPortfolioId,
		    CCY ccy  
		from 
		PTL_CASH_POSITION_FLOW
		WHERE 1=1 and PORTFOLIO_ID = #{subPortfolioId,jdbcType=VARCHAR}

    		AND HODING_TYPE =  #{hodingType}


    		AND CCY =  #{ccy}

		GROUP BY PORTFOLIO_ID,CCY

select IFNULL(SUM(PF.AMOUNT),0) avaAmt, PF.PORTFOLIO_ID subPortfolioId, PF.CCY ccy from PTL_CASH_POSITION_FLOW PF
INNER JOIN PTL_CAPACCT_INFO PC ON PC.PORTFOLIO_ID=PF.PORTFOLIO_ID AND PC.ACCT_NO=PF.ACCT_ID AND PC.ACCT_TYPE='${acctType}' AND PF.CCY=PC.CCY WHERE 1=1 and PF.PORTFOLIO_ID = #{subPortfolioId,jdbcType=VARCHAR}
AND PF.HODING_TYPE = #{hodingType}
AND PF.CCY = #{ccy}
GROUP BY PF.PORTFOLIO_ID,PF.CCY

select T1.PORTFOLIO_ID id, CONCAT(T1.PORTFOLIO_ID ,CONCAT( ':' , T1.PORTFOLIO_NAME)) text from PTL_PORTFOLIO T1 inner join PTL_PORTFOLIO_AUTHORITY T2 on T2.PORTFOLIO_ID = T1.PORTFOLIO_ID and T2.USER_ID = #{loginUserName} where 1=1
AND T1.PORTFOLIO_TYPE = #{portfolioType}
AND T1.INVEST_YESORNO = #{investYesOrNo}
AND (T1.PORTFOLIO_ID like concat('%',concat(#{search},'%')) OR T1.PORTFOLIO_NAME like concat('%',concat(#{search},'%')))
